<?php
require '../config/db.php';require '../config/auth.php';require_role('admin','login.php');$u=current_user();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$a=$_POST['action']??'toggle';if($a==='toggle'&&$id){$pdo->prepare("UPDATE users SET status=IF(status='active','inactive','active') WHERE id=? AND role='parishioner'")->execute([$id]);log_activity($pdo,$u['id'],'Toggled parishioner status','User #'.$id);}redirect('users.php');}
$q='';$sql="SELECT u.*,(SELECT COUNT(*) FROM appointments a WHERE a.user_id=u.id) appointment_count FROM users u WHERE role='parishioner'";$p=[];if($q!==''){$sql.=' AND (u.full_name LIKE ? OR u.email LIKE ? OR u.contact_number LIKE ?)';$like='%'.$q.'%';$p=[$like,$like,$like];}$sql.=' ORDER BY created_at DESC';$s=$pdo->prepare($sql);$s->execute($p);$rows=$s->fetchAll();
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Users</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><div class="shell"><?php include 'includes/sidebar.php'?><main class="main"><header class="topbar"><div><button class="btn light mobile-toggle" data-nav-toggle>☰</button><div class="eyebrow">Directory</div><h1>Parishioners.</h1></div></header><section class="card table-wrap" data-live-scope><div class="live-filter-bar"><label class="field live-search-field">Search<input class="search" type="search" data-live-search placeholder="Search name, email, phone, address..."></label><label class="field">Status<select data-live-filter="status"><option value="">All statuses</option><option value="active">Active</option><option value="inactive">Inactive</option></select></label><button type="button" class="btn light" data-live-clear>Clear</button><span class="live-filter-meta" data-live-count></span></div><table class="table"><thead><tr><th>Name</th><th>Contact</th><th>Birthday / Gender</th><th>Joined</th><th>Appointments</th><th>Status</th><th></th></tr></thead><tbody data-live-list><tr data-live-empty class="live-empty" hidden><td colspan="7">No parishioners match your search.</td></tr><?php foreach($rows as $r):?><tr data-live-item data-status="<?=e(strtolower($r['status']))?>" data-search="<?=e(strtolower($r['full_name'].' '.$r['email'].' '.$r['contact_number'].' '.$r['address']))?>"><td><b><?=e($r['full_name'])?></b><br><span class="muted"><?=e($r['address'])?></span></td><td><?=e($r['email'])?><br><?=e($r['contact_number'])?></td><td><?=date('M j, Y',strtotime($r['birthday']))?><br><?=e($r['gender'])?></td><td><?=date('M j, Y',strtotime($r['created_at']))?></td><td><?=$r['appointment_count']?></td><td><span class="badge"><?=e($r['status'])?></span></td><td><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="action" value="toggle"><button class="btn light small"><?=$r['status']==='active'?'Deactivate':'Activate'?></button></form></td></tr><?php endforeach?></tbody></table></section></main></div><script src="../assets/js/script.js"></script></body></html>
